import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.lxr64Vqo.js";const g=JSON.parse('{"title":"Nuvio Streaming Guide","description":"","frontmatter":{},"headers":[],"relativePath":"clients/stremio-nuvio.md","filePath":"clients/stremio-nuvio.md","lastUpdated":1795172190000}'),n={name:"clients/stremio-nuvio.md"};function r(s,t,l,d,p,u){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="nuvio-streaming-guide" tabindex="-1">Nuvio Streaming Guide <a class="header-anchor" href="#nuvio-streaming-guide" aria-label="Permalink to &quot;Nuvio Streaming Guide&quot;">​</a></h1><p>NoxMedia implements the official Addon v3 Protocol for modern streaming clients, featuring full support for <a href="https://github.com/nuvio-app" target="_blank" rel="noreferrer">Nuvio</a>.</p><hr><h2 id="important-notice-stremio-support-status" tabindex="-1">Important Notice: Stremio Support Status <a class="header-anchor" href="#important-notice-stremio-support-status" aria-label="Permalink to &quot;Important Notice: Stremio Support Status&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Stremio Integration Temporarily On Hold</strong>: Direct playback in Stremio is currently on hold while we resolve an issue related to Stremio&#39;s handling of local HTTP streaming URLs on localhost configurations. A dedicated fix is actively in progress and will arrive in an upcoming release.</p><p>In the interim, <strong>Nuvio</strong> is the officially recommended client for addon-based streaming on Android, Windows, macOS, and Web.</p></div><hr><h2 id="nuvio-setup" tabindex="-1">Nuvio Setup <a class="header-anchor" href="#nuvio-setup" aria-label="Permalink to &quot;Nuvio Setup&quot;">​</a></h2><p><a href="https://github.com/nuvio-app" target="_blank" rel="noreferrer">Nuvio</a> is a sleek, modern streaming client designed for fast exploration and playback of custom media catalogs.</p><h3 id="_1-retrieve-manifest-url" tabindex="-1">1. Retrieve Manifest URL <a class="header-anchor" href="#_1-retrieve-manifest-url" aria-label="Permalink to &quot;1. Retrieve Manifest URL&quot;">​</a></h3><p>With the NoxMedia server active on your host device, your manifest endpoint is:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://&lt;YOUR_SERVER_IP&gt;:7788/manifest.json</span></span></code></pre></div><p><em>(For example: <code>http://192.168.1.15:7788/manifest.json</code> or <code>http://127.0.0.1:7788/manifest.json</code> if running locally on the same device).</em></p><h3 id="_2-add-provider-in-nuvio" tabindex="-1">2. Add Provider in Nuvio <a class="header-anchor" href="#_2-add-provider-in-nuvio" aria-label="Permalink to &quot;2. Add Provider in Nuvio&quot;">​</a></h3><ol><li>Open <strong>Nuvio</strong> on your Android, Windows, Mac, or Web client.</li><li>Navigate to <strong>Settings</strong> -&gt; <strong>Providers &amp; Addons</strong> -&gt; <strong>Add Custom Provider</strong>.</li><li>Paste your full manifest URL:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.1.15:7788/manifest.json</span></span></code></pre></div></li><li>Click <strong>Connect / Install</strong>.</li><li>Your Telegram libraries and AI custom shelves will populate the home feed immediately.</li></ol><hr><h2 id="capabilities-in-nuvio" tabindex="-1">Capabilities in Nuvio <a class="header-anchor" href="#capabilities-in-nuvio" aria-label="Permalink to &quot;Capabilities in Nuvio&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:center;">Support</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Catalog Exploration</strong></td><td style="text-align:center;">Supported</td><td style="text-align:left;">Movies, TV Series, Anime, and all Custom AI Shelves</td></tr><tr><td style="text-align:left;"><strong>Rich Metadata</strong></td><td style="text-align:center;">Supported</td><td style="text-align:left;">Synopses, cast info, ratings, and high-resolution posters</td></tr><tr><td style="text-align:left;"><strong>Direct Stream Resolving</strong></td><td style="text-align:center;">Supported</td><td style="text-align:left;">Real-time byte streaming without local storage caching</td></tr><tr><td style="text-align:left;"><strong>Multiple Audio &amp; Subtitles</strong></td><td style="text-align:center;">Supported</td><td style="text-align:left;">Embedded audio tracks and subtitle selection</td></tr><tr><td style="text-align:left;"><strong>Multi-Quality Sources</strong></td><td style="text-align:center;">Supported</td><td style="text-align:left;">1080p, 4K, 720p, and Remux stream selectors</td></tr></tbody></table>',17)])])}const h=e(n,[["render",r]]);export{g as __pageData,h as default};
